const QVector<Airport> &airportSeed()
{
    static const QVector<Airport> table = [] {
        QVector<Airport> v;
        v.reserve(int(sizeof(kRows) / sizeof(kRows[0])));
        for (const Row &r : kRows) {
            Airport a;
            a.icao = QString::fromLatin1(r.icao);
            a.iata = QString::fromLatin1(r.iata);
            a.name = QString::fromUtf8(r.name);
            a.city = QString::fromUtf8(r.city);
            a.country = QString::fromUtf8(r.country);
            a.timeZone = QString::fromLatin1(r.tz);
            a.lat = r.lat;
            a.lon = r.lon;
            a.seeded = true;
            v.append(a);
        }
        return v;
    }();
    return table;
}
